package hyperneat

import (
	"errors"
	"math"

	"github.com/cookiengineer/goneat/engine/neat"
)

// Solver is a substrate network whose connection weights were generated by a
// CPPN. It is a normal feed-forward network once constructed, so it can be
// activated like any other.
type Solver struct {
	layout     SubstrateLayout
	options    Options
	genome     *neat.Genome
	network    *neat.Network
	inputIDs   []int
	outputIDs  []int
	biasIDs    []int
	hiddenIDs  []int
	points     map[int]Point
	linkPoints map[int][2]Point
}

// NewSolver builds a substrate network from a layout and a CPPN.
func NewSolver(layout SubstrateLayout, cppn *CPPN, options Options) (*Solver, error) {
	if layout == nil || cppn == nil {
		return nil, errors.New("hyperneat: nil layout or cppn")
	}
	if layout.OutputCount() < 1 {
		return nil, errors.New("hyperneat: substrate needs at least one output")
	}
	if layout.BiasCount() > 1 {
		return nil, errors.New("hyperneat: at most one bias node is supported")
	}

	solver := &Solver{
		layout:     layout,
		options:    options,
		points:     map[int]Point{},
		linkPoints: map[int][2]Point{},
	}
	genome := &neat.Genome{ID: -1}

	nextID := 0
	addNodes := func(count int, nodeType NodeType, activation neat.ActivationType) ([]int, error) {
		ids := make([]int, 0, count)
		for index := 0; index < count; index++ {
			point, err := layout.NodePosition(index, nodeType)
			if err != nil {
				return nil, err
			}
			id := nextID
			nextID++
			genome.Nodes = append(genome.Nodes, neat.NodeGene{ID: id, Type: toNeatType(nodeType), Activation: activation})
			solver.points[id] = point
			ids = append(ids, id)
		}
		return ids, nil
	}

	var err error
	if solver.biasIDs, err = addNodes(layout.BiasCount(), NodeBias, neat.ActivationLinear); err != nil {
		return nil, err
	}
	if solver.inputIDs, err = addNodes(layout.InputCount(), NodeInput, neat.ActivationLinear); err != nil {
		return nil, err
	}
	if solver.hiddenIDs, err = addNodes(layout.HiddenCount(), NodeHidden, options.HiddenActivation); err != nil {
		return nil, err
	}
	if solver.outputIDs, err = addNodes(layout.OutputCount(), NodeOutput, options.OutputActivation); err != nil {
		return nil, err
	}

	innovation := 0
	connect := func(source, target int) error {
		sourcePoint := solver.points[source]
		targetPoint := solver.points[target]
		outputs, err := cppn.Query(sourcePoint, targetPoint)
		if err != nil {
			return err
		}
		weight, express := expressWeight(outputs, options)
		if !express {
			return nil
		}
		innovation++
		genome.Connections = append(genome.Connections, neat.ConnectionGene{
			Innovation: innovation,
			In:         source,
			Out:        target,
			Weight:     weight,
			Enabled:    true,
		})
		solver.linkPoints[innovation] = [2]Point{sourcePoint, targetPoint}
		return nil
	}

	if len(solver.hiddenIDs) == 0 {
		for _, source := range append(append([]int{}, solver.biasIDs...), solver.inputIDs...) {
			for _, target := range solver.outputIDs {
				if err := connect(source, target); err != nil {
					return nil, err
				}
			}
		}
	} else {
		for _, source := range append(append([]int{}, solver.biasIDs...), solver.inputIDs...) {
			for _, target := range solver.hiddenIDs {
				if err := connect(source, target); err != nil {
					return nil, err
				}
			}
		}
		for _, source := range solver.hiddenIDs {
			for _, target := range solver.outputIDs {
				if err := connect(source, target); err != nil {
					return nil, err
				}
			}
		}
		for _, source := range solver.biasIDs {
			for _, target := range solver.outputIDs {
				if err := connect(source, target); err != nil {
					return nil, err
				}
			}
		}
	}

	if len(genome.Connections) == 0 {
		return nil, errors.New("hyperneat: cppn expressed no links (lower the link threshold)")
	}

	network, err := neat.NewNetwork(genome)
	if err != nil {
		return nil, err
	}
	solver.genome = genome
	solver.network = network
	return solver, nil
}

// expressWeight decides whether a CPTN output expresses a link and returns its
// scaled weight. With LEO, the second output gates the first. Otherwise the
// absolute first output must exceed the link threshold and is normalized into
// the weight range.
func expressWeight(outputs []float64, options Options) (float64, bool) {
	if len(outputs) == 0 {
		return 0, false
	}
	if options.UseLEO && len(outputs) > 1 {
		if outputs[1] <= 0 {
			return 0, false
		}
		return outputs[0] * options.WeightRange, true
	}
	magnitude := math.Abs(outputs[0])
	if magnitude < options.LinkThreshold {
		return 0, false
	}
	denominator := 1 - options.LinkThreshold
	if denominator <= 0 {
		denominator = 1
	}
	weight := (magnitude - options.LinkThreshold) / denominator * options.WeightRange
	if math.Signbit(outputs[0]) {
		weight = -weight
	}
	return weight, true
}

// expressWeightGradient returns d(weight)/d(cppnOutput[0]) for the link
// expression rule. It is used when differentiating a substrate with respect to
// the CPPN that generated it.
func expressWeightGradient(outputs []float64, options Options) float64 {
	if len(outputs) == 0 {
		return 0
	}
	if options.UseLEO && len(outputs) > 1 {
		if outputs[1] <= 0 {
			return 0
		}
		return options.WeightRange
	}
	if math.Abs(outputs[0]) < options.LinkThreshold {
		return 0
	}
	denominator := 1 - options.LinkThreshold
	if denominator <= 0 {
		denominator = 1
	}
	return options.WeightRange / denominator
}

// Genome returns the constructed substrate genome (useful for inspection and
// graph export).
func (s *Solver) Genome() *neat.Genome { return s.genome }

// Network returns the substrate phenotype network. Its connections read weights
// from the genome, so weight updates are reflected without rebuilding.
func (s *Solver) Network() *neat.Network { return s.network }

// LinkPoints returns the source and target substrate coordinates of a
// connection identified by its innovation number.
func (s *Solver) LinkPoints(innovation int) (Point, Point, bool) {
	points, ok := s.linkPoints[innovation]
	if !ok {
		return Point{}, Point{}, false
	}
	return points[0], points[1], true
}

// InputCount returns the substrate input count.
func (s *Solver) InputCount() int { return len(s.inputIDs) }

// OutputCount returns the substrate output count.
func (s *Solver) OutputCount() int { return len(s.outputIDs) }

// LinkCount returns the number of expressed links.
func (s *Solver) LinkCount() int { return len(s.genome.Connections) }

// NodeCount returns the number of substrate neurons.
func (s *Solver) NodeCount() int { return len(s.genome.Nodes) }

// Activate evaluates the substrate network.
func (s *Solver) Activate(inputs, outputs []float64) error {
	return s.network.Activate(inputs, outputs)
}

// Point returns the substrate coordinate of a neuron ID.
func (s *Solver) Point(id int) (Point, bool) {
	point, ok := s.points[id]
	return point, ok
}

func toNeatType(nodeType NodeType) neat.NodeType {
	switch nodeType {
	case NodeBias:
		return neat.NodeBias
	case NodeInput:
		return neat.NodeInput
	case NodeOutput:
		return neat.NodeOutput
	default:
		return neat.NodeHidden
	}
}
